quickStart.codeSnippet:
{
  "name": "my-plugin",
  "version": "1.0.0"
}

import { Plannotator } from 'plannotator';

const workspace = new Plannotator();
workspace.connectAgent('claude-code');

import { NodAgent } from '@n8n/nod';

const agent = new NodAgent({ model: 'gpt-4o' });
await agent.run({ task: 'Cancel my unused trial subscriptions' });

import { CodeReviewPipeline } from '@alibaba-group/open-code-review';

const reviewer = new CodeReviewPipeline({ provider: 'openai' });
await reviewer.analyzePullRequest({ prId: '123' });

import { createChromeDevToolsMCP } from 'chrome-devtools-mcp';

const mcpServer = createChromeDevToolsMCP();
await mcpServer.start();

import { AgAgentClient } from '@ag-ui/core';

const client = new AgAgentClient({ endpoint: 'https://api.ag-ui.com/agent' });
await client.connect();

import { Button } from '@astryxdesign/core';

export default function App() {
  return <Button variant="primary">Hello Astryx</Button>;
}

import { Univer, UniverCorePreset } from '@univerjs/core';
import { UniverSheetsPreset } from '@univerjs/sheets';

const univer = new Univer({
  presets: [UniverCorePreset(), UniverSheetsPreset()],
});
univer.createUnit('sheet', {});

import { MausBot } from '@openmaus/core';

const bot = new MausBot({ model: 'claude-3.5-sonnet', vm: 'isolated' });
bot.startTask('Refactor database schema');

import { T3ControlPlane } from 't3code';

T3ControlPlane.init({
  providers: ['claude-code', 'codex'],
  syncMobile: true
});

import { Plannotator } from 'plannotator';

const workspace = new Plannotator();
workspace.connectAgent('claude-code');

const client = new OpenAI({ baseURL: 'http://localhost:port/v1' });
const res = await client.chat.completions.create({
  model: 'deepseek-v4.1-flash',
  messages: [{ role: 'user', content: 'Hello' }]
});

import { renderVideo } from 'hyperframes';

await renderVideo({
  template: '<div>Hello HyperFrames</div>',
  output: 'output.mp4'
});
